import os
from google import genai

client = genai.Client(
    api_key=os.environ.get("GEMINI_API_KEY"),
)

generation_config = {
    'max_output_tokens': 4096,
    'thinking_level': 'medium',
}

interaction = client.interactions.create(
    model='models/gemini-3.8-flash',
    input=[
        {
            'type': 'text',
            'text': 'Media-access diagnostic only; do not assign quality scores. Inspect only the attached video, without inferring content from the filename or generic relaxation scripts. Report: (1) full duration; (2) exact spoken words from 32 seconds to the end with timestamps, separating what you HEAR from any visible captions; (3) concrete visible objects and their positions at 10 seconds and 30 seconds; (4) time and visual content of the main scene transition; (5) audible voice characteristics, background music or other sounds, and what is heard after the final spoken words. Explicitly state separately whether video frames and audio are accessible. If a modality is unavailable, say so instead of substituting captions, metadata, or guesses. Do not provide a score.',
        },
        {
            'type': 'video',
        },
    ],
    generation_config=generation_config,
)

for step in interaction.steps:
    if step.type == 'model_output' and step.content:
        for part in step.content:
            if part.type == 'text':
                print(part.text)
